export class Documented {
    /** The byte length of a `Documented` */
    static SIZE = 7;

    /**
     * The alignment of an array of `Documented`: its largest scalar's size
     *
     * @type {4}
     */
    static ALIGNMENT = 4;

    /** @type {number} */
    #one;
    /** @type {number} */
    #two;
    /** @type {number} */
    #undocumented;

    /**
     * Reads a `Documented` at `offset` in `bytes`, eagerly, so that it
     * doesn't keep them alive
     *
     * @param {Uint8Array} bytes
     * @param {number} [offset]
     * @throws {DecodeError} If `bytes` end before the `Documented` does.
     */
    constructor(bytes, offset = 0) {
        this.#one = readUint8(bytes, offset);
        this.#two = readUint16(bytes, offset + 1);
        this.#undocumented = readUint32(bytes, offset + 3);
    }

    /**
     * Writes a `Documented`
     *
     * @param {DocumentedFields} fields
     * @returns {Uint8Array}
     */
    static serialize(fields) {
        const bytes = new Uint8Array(Documented.SIZE);
        Documented.writeAt(bytes, 0, fields);

        return bytes;
    }

    /**
     * Writes `Documented`s one after another, as an array of them holds them
     *
     * @param {readonly DocumentedFields[]} items
     * @returns {Uint8Array}
     */
    static serializeArray(items) {
        const bytes = new Uint8Array(items.length * Documented.SIZE);
        const writer = new StructWriter(bytes);
        for (const fields of items) {
            Documented.write(writer, fields);
        }

        return bytes;
    }

    /**
     * Writes a `Documented` at the writer's position
     *
     * @param {StructWriter} writer
     * @param {DocumentedFields} fields
     * @returns {void}
     */
    static write(writer, fields) {
        writer.setUint8(fields.one);
        writer.setUint16(fields.two);
        writer.setUint32(fields.undocumented);
    }

    /**
     * Writes a `Documented` at `offset` in `bytes`
     *
     * @param {Uint8Array} bytes
     * @param {number} offset
     * @param {DocumentedFields} fields
     * @returns {void}
     * @throws {RangeError} If `bytes` end before the `Documented` does.
     */
    static writeAt(bytes, offset, fields) {
        writeUint8(bytes, offset, fields.one);
        writeUint16(bytes, offset + 1, fields.two);
        writeUint32(bytes, offset + 3, fields.undocumented);
    }

    /** @returns {number} A field's documentation, of one line */
    one() {
        return this.#one;
    }

    /**
     * A field's documentation,
     * of two lines
     *
     * @returns {number}
     */
    two() {
        return this.#two;
    }

    /** @returns {number} */
    undocumented() {
        return this.#undocumented;
    }
}

/**
 * The fields of a `Documented`, to write
 *
 * @typedef {object} DocumentedFields
 * @property {number} one A field's documentation, of one line
 * @property {number} two A field's documentation, of two lines
 * @property {number} undocumented
 */

/** An array of `Documented`s, which reads each struct when it's asked for */
export class DocumentedArray {
    /** @type {Uint8Array} */
    #bytes;
    /** @type {number} */
    #length;

    /**
     * Views the array at `position`, as its parent's getter finds it
     *
     * @param {ByteBuffer} buffer
     * @param {number} position
     * @throws {DecodeError} If the array lies outside the bytes.
     */
    constructor(buffer, position) {
        this.#bytes = buffer.getStructArray(position, Documented.SIZE);
        this.#length = this.#bytes.length / Documented.SIZE;
    }

    /** @returns {number} The number of structs */
    length() {
        return this.#length;
    }

    /**
     * Reads struct `index`
     *
     * @param {number} index
     * @returns {Documented}
     * @throws {RangeError} If the array has no struct `index`.
     */
    get(index) {
        if (!(Number.isInteger(index) && index >= 0 && index < this.#length)) {
            throw new RangeError(
                `Struct ${index} is outside the array of ${this.#length}`
            );
        }

        return new Documented(this.#bytes, index * Documented.SIZE);
    }
}
